export const title = "How to Build a Paper Inbox System for a Desk With No Drawers";
export const metaTitle = "How to Build a Paper Inbox System for a Desk";
export const metaDescription = "Create a paper inbox for a drawer-free desk with review, action, reference, and appropriate disposal routes. A research-based guide from DeskFinds.";
export const author = "Jamie Cole, Lead Product Researcher";
export const datePublished = "2026-11-17";
